'AC-meta.residue.2'; from __future__ import annotations; from pathlib import Path; from tests.tooling.test_epic_residue_ratchet import EPIC_RESIDUE_BASELINE; REPO = Path(__file__).resolve().parents[2]; PROJECT_DIR = REPO / 'docs' / 'project'; SSOT_DIR = REPO / 'docs' / 'ssot'; NON_EPIC_DOCS_PROJECT_ALLOWLIST: frozenset[str] = frozenset({'AC-AUDIT-2026-05-04.md', 'AUDITS.md', 'DECISIONS.md', 'DELIVERY_ENGINE_RECOMMENDATIONS.md', 'README.md', 'traceability-exceptions.md'})
def _project_directory_violations(project_dir: Path, allowlist: set[str]) -> list[str]: entries = list(project_dir.iterdir()); violations = [f'unexpected directory: {entry.name}' for entry in entries if entry.is_dir()]; actual_files = {entry.name for entry in entries if entry.is_file()}; violations += [f'unexpected file: {name}' for name in sorted(actual_files - allowlist)]; return violations
def test_docs_ssot_directory_is_retired() -> None: assert not SSOT_DIR.exists(), "docs/ssot/ must not exist — it was retired in #1823 (Package-ization 4/4, terminal). A package-owned concept belongs in that package's common/<pkg>/readme.md / contract.py; cross-cutting gate data belongs in common/meta/data/ (or another package's data/). If this is a deliberate, reviewed exception, update this test."
def test_docs_project_directory_listing_is_frozen() -> None: allowlist = set(EPIC_RESIDUE_BASELINE) | set(NON_EPIC_DOCS_PROJECT_ALLOWLIST); violations = _project_directory_violations(PROJECT_DIR, allowlist); assert not violations, f'docs/project/ grew outside the #1823 terminal allowlist — new work belongs in a package (ac-workflow), and docs/project/ is a closed, shrink-only home (EPIC-*.md residue rows, plus a fixed set of non-EPIC governance docs). If this is a deliberate, reviewed exception, add it to NON_EPIC_DOCS_PROJECT_ALLOWLIST (or, for a new EPIC file, to the EPIC residue baseline instead — see test_epic_residue_ratchet.py).\nviolations: {violations}'
def test_project_directory_violations_catches_rogue_file_and_subdirectory(tmp_path: Path) -> None: (tmp_path / 'README.md').write_text('allowed', encoding='utf-8'); (tmp_path / 'sneaky-new-doc.md').write_text('not allowlisted', encoding='utf-8'); rogue_dir = tmp_path / 'sneaky-subdir'; rogue_dir.mkdir(); (rogue_dir / 'hidden.md').write_text('invisible to a file-only scan', encoding='utf-8'); violations = _project_directory_violations(tmp_path, {'README.md'}); assert 'unexpected file: sneaky-new-doc.md' in violations; assert 'unexpected directory: sneaky-subdir' in violations; assert len(violations) == 2; _m1_tmp = tmp_path / '_m1'; _m1_tmp.mkdir(exist_ok=True); (_m1_tmp / 'README.md').write_text('allowed', encoding='utf-8'); assert _project_directory_violations(_m1_tmp, {'README.md', 'OTHER.md'}) == []
